CREATE TABLE quality_issue (id INTEGER PRIMARY KEY AUTOINCREMENT,qb_id INTEGER NOT NULL,variant_index INTEGER,issue_type TEXT NOT NULL,suggested_action TEXT NOT NULL,reason TEXT,suggested_value TEXT,confidence REAL,status TEXT DEFAULT 'pending',created_at TEXT,reviewed_at TEXT,reviewed_by INTEGER, target_qb_id INTEGER DEFAULT NULL, new_cat2 TEXT DEFAULT NULL, review_version TEXT, review_task_id TEXT, trigger_reason TEXT, variant_key TEXT NOT NULL DEFAULT '', source_question TEXT DEFAULT NULL, source_cat2 TEXT DEFAULT NULL, issue_fingerprint TEXT, superseded_at TEXT, superseded_by INTEGER);
